//@version=4
study("My Script", overlay=true)
var l=label.new(bar_index, close, yloc=yloc.abovebar, text="Label")
label.set_x(l,bar_index)
label.set_tooltip(l, "Label Tooltip")

//@version=4
study("My Script", overlay = true)
var l = label.new(bar_index, high, text="Right\n aligned\n text", textalign=text.align_right)
label.set_xy(l, bar_index, high)

//@version=6
// Editorial example; not compiled or executed in Pine.
indicator("Unmatched bool switch")
bool selected = switch 2
    1 => true
plot(selected ? 1 : 0, "Expected zero")

//@version=6
// Editorial example; not compiled or executed in Pine.
indicator("Footprint delta and POC")
footprint fp = request.footprint(100)
float deltaValue = na
float pocMiddle = na
if not na(fp)
    deltaValue := fp.delta()
    volume_row pocRow = fp.poc()
    if not na(pocRow)
        pocMiddle := math.avg(pocRow.up_price(), pocRow.down_price())
plot(deltaValue, "Footprint delta", style = plot.style_columns)
plot(pocMiddle, "POC midpoint", force_overlay = true)

//@version=6
// Editorial example; not compiled or executed in Pine.
indicator("Line wrapping")
float typical = (
    high + low + close
) / 3
[
    macd,
    signal,
    hist
] = ta.macd(typical, 12, 26, 9)
plot(hist)

//@version=6
// Editorial example; not compiled or executed in Pine.
indicator("Symbol ISIN", overlay = true)
var table info = table.new(position.top_right, 1, 1)
if barstate.islast
    string isin = syminfo.isin
    table.cell(info, 0, 0, na(isin) or isin == "" ? "ISIN unavailable" : isin)

